public static int indexOfExtension(String filename) {
  if (filename == null) {
    return -1;
  }
  int lastSeparatorIndex = indexOfLastSeparator(filename);
  int extensionIndex = filename.lastIndexOf('.');
  if (extensionIndex > lastSeparatorIndex) {
    return extensionIndex;
  } else {
    return -1;
  }
}

public boolean isExpired(long timestamp, long expiredThreshold) {
    if (timestamp < 0 || expiredThreshold < 0) {
        throw new IllegalArgumentException("Invalid input: timestamp and expiredThreshold must be non-negative");
    }
    long currentTime = System.currentTimeMillis();
    long lastUpdateTime = currentTime - timestamp;
    return lastUpdateTime > expiredThreshold;
}

public Edge edgeToNext() {
    if (currentNode == null) {
        throw new IllegalStateException("No current node is set");
    }
    if (nextNode == null) {
        throw new IllegalStateException("No next node is set");
    }
    if (currentNode.isVirtual() || nextNode.isVirtual()) {
        throw new IllegalStateException("Cannot create an edge between virtual nodes");
    }
    return new Edge(currentNode, nextNode);
}

public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
  if (str == null || substring == null) {
    return false;
  }
  if (index < 0 || index >= str.length()) {
    return false;
  }
  if (substring.length() > str.length() - index) {
    return false;
  }
  for (int i = 0; i < substring.length(); i++) {
    if (str.charAt(index + i) != substring.charAt(i)) {
      return false;
    }
  }
  return true;
}

